(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20+Math.cos(y*0.02-t*0.15)*15;
  const w1y = Math.cos(y*0.018-t*0.18)*20+Math.sin(x*0.022+t*0.25)*15;
  const w2x = Math.sin((x+w1x)*0.025-t*0.3)*10+Math.cos((y+w1y)*0.03+t*0.2)*8;
  const w2y = Math.cos((y+w1y)*0.028+t*0.25)*10+Math.sin((x+w1x)*0.02-t*0.35)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*55,0.085,1.8,1.05]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const decay=1.0/(1.0+d*0.008);
    aS+=Math.sin(d*f-t*sp)*amp*decay;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp*decay;
    wS+=Math.sin(d*f*1.3-t*sp*0.8+2.0)*amp*decay*0.5;
  }
  const act=aS/8,inh=iS/8,wav=wS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.07+sy*0.05-t*0.6)+Math.cos(sx*0.05-sy*0.08+t*0.9))/4+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.065-ang*2+t*0.8)*0.6+Math.sin(dist*0.035+ang*5-t*2.0)*0.5)*0.25;
  const fine=Math.sin(sx*0.8)*Math.sin(sy*0.8)*Math.sin((sx+sy)*0.5)*Math.sin((sx-sy)*0.6)*0.12;
  const reaction=Math.tanh((act*1.055-inh*1.062+bg*0.25+spiral+wav*0.3+fine)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin((sx-sy)*0.12-t*0.7)*0.3)*1.5)*0.3;
  const cell2=Math.tanh((Math.sin(sx*0.22+t*0.3)*Math.cos(sy*0.18-t*0.2))*1.2)*0.12;
  const edgeDet=Math.abs(reaction-Math.tanh((act*1.02-inh*1.04+bg*0.25+spiral)*2.0));
  const blend=reaction*0.6+cell*0.2+cell2*0.1+edgeDet*0.1;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,95],[18,85,120],[25,130,130],[50,160,120],[140,175,90],[210,190,70],[230,150,65],[215,100,70],[180,60,75],[120,35,75],[60,20,65],[25,12,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const glow=Math.max(0,reaction)*0.35;
  const edge=edgeDet>0.12?1.18:1.0;
  const vignette=1.0-dist*0.0008;
  const m=lum*edge*Math.max(0.3,vignette)+glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*m)|0
  ];
}
